/**
 * Perform an HTTP GET request using the Fetch API with automatic retries on failure.
 *
 * The function attempts to fetch the given `url` up to `retries + 1` times (the
 * initial attempt plus the specified number of retries). If a request fails
 * (i.e., the `fetch` call rejects), it will wait `delayMs` milliseconds before
 * trying again. When the final retry also fails, the original error is
 * re‑thrown.
 *
 * @param {string} url - The URL to request.
 * @param {number} [retries=3] - The maximum number of **additional** attempts
 *   after the initial request. A value of `0` means the request is attempted only
 *   once. Must be a non‑negative integer.
 * @param {number} [delayMs=500] - The amount of time, in milliseconds, to wait
 *   between retry attempts. Ignored if `retries` is `0`. Must be a non‑negative
 *   integer.
 *
 * @returns {Promise<Response>} A promise that resolves with the `Response` object
 *   from the successful fetch call.
 *
 * @throws {Error} Propagates the error from the final failed fetch attempt.
 * @throws {Error} Throws an `"unreachable"` error only if the internal loop logic
 *   is somehow corrupted (this should never happen under normal circumstances).
 *
 * @example
 * ```ts
 * import { fetchWithRetry } from './utils';
 *
 * async function loadData() {
 *   try {
 *     const response = await fetchWithRetry('https://api.example.com/data', 5, 1000);
 *     const json = await response.json();
 *     console.log('Data:', json);
 *   } catch (err) {
 *     console.error('Failed to fetch after retries:', err);
 *   }
 * }
 *
 * loadData();
 * ```
 *
 * @async
 */
export async function fetchWithRetry(
  url: string,
  retries = 3,
  delayMs = 500,
): Promise<Response> {
  for (let i = 0; i <= retries; i++) {
    try {
      return await fetch(url);
    } catch (e) {
      if (i === retries) throw e;
      await new Promise((r) => setTimeout(r, delayMs));
    }
  }
  // This line is theoretically unreachable because the loop either returns
  // a successful response or throws after the last retry.
  throw new Error('unreachable');
}
